const authHeader = $input.first().json.headers?.authorization || '';
if (!authHeader.startsWith('Bearer ')) {
  return [{ json: { _unauthorized: true } }];
}
const token = authHeader.replace('Bearer ', '');
try {
  const decoded = JSON.parse(Buffer.from(token, 'base64').toString());
  if (decoded.exp && Date.now() > decoded.exp) {
    return [{ json: { _unauthorized: true } }];
  }
  return [{ json: { ...$input.first().json, _user: decoded } }];
} catch(e) {
  return [{ json: { _unauthorized: true } }];
}

// Gather data from all three fetches (sequential: Projects → Scripts → Concepts → here)
const projectsData = $('Fetch Projects').first().json;
const scriptsData = $('Fetch Scripts').first().json;
const conceptsData = $input.first().json;

const projects = (projectsData.records || []);
const scripts = (scriptsData.records || []);
const concepts = (conceptsData.records || []);

// --- Projects stats ---
const projectsByStatus = {};
for (const p of projects) {
  const status = (p.fields.status || p.fields.Status || 'Unknown');
  projectsByStatus[status] = (projectsByStatus[status] || 0) + 1;
}

// --- Concepts stats ---
let conceptsApproved = 0, conceptsPending = 0, conceptsRejected = 0;
for (const c of concepts) {
  const status = (c.fields.status || c.fields.Status || '').toLowerCase();
  if (status.includes('approved') || status.includes('approve')) conceptsApproved++;
  else if (status.includes('rejected') || status.includes('reject')) conceptsRejected++;
  else conceptsPending++;
}

// --- Scripts stats ---
let scriptsDelivered = 0, scriptsInReview = 0, scriptsDraft = 0, scriptsOther = 0;
for (const s of scripts) {
  const status = (s.fields.status || s.fields.Status || '').toLowerCase();
  if (status.includes('delivered') || status.includes('complete')) scriptsDelivered++;
  else if (status.includes('review') || status.includes('client')) scriptsInReview++;
  else if (status.includes('draft') || status.includes('writing')) scriptsDraft++;
  else scriptsOther++;
}

// --- Recent projects (top 5 by created_at desc) ---
const sortedProjects = [...projects].sort((a, b) => {
  const dateA = a.fields.created_at || a.createdTime || '';
  const dateB = b.fields.created_at || b.createdTime || '';
  return dateB.localeCompare(dateA);
});

const recentProjects = sortedProjects.slice(0, 5).map(p => ({
  id: p.id,
  client_code: p.fields.client_code || '',
  brand_name: p.fields.brand_name || '',
  status: p.fields.status || p.fields.Status || '',
  num_scripts: p.fields.num_scripts || 0,
  created_at: p.fields.created_at || p.createdTime || '',
  pm_email: p.fields.pm_email || ''
}));

return [{
  json: {
    success: true,
    projects: {
      total: projects.length,
      by_status: projectsByStatus
    },
    concepts: {
      total: concepts.length,
      approved: conceptsApproved,
      pending: conceptsPending,
      rejected: conceptsRejected
    },
    scripts: {
      total: scripts.length,
      delivered: scriptsDelivered,
      in_review: scriptsInReview,
      draft: scriptsDraft
    },
    recent_projects: recentProjects
  }
}];
